import logging
from taf.sbts.oam.coam.admin.exceptions import DataNotAvailable
from taf.sbts.oam.coam.admin.utils import raise_value_error


class SoftwareMgmtInterface21B(object):
    def update_software(self, sw_package, should_activate=True, timeout=600, should_reset_radios=False, **kwargs):
        """
        Perform software update.

        :param string sw_package: Path to software package. URLs are also supported, it will automatically download and
        update the software then.
        :param boolean should_activate: Activate software flag.
        :param boolean should_reset_radios: Activate reset radios flag.
        :param int timeout: Time to wait for positive procedure result.
        :raise DataNotAvailable: Raised if operation is invalid from Node-B side.
        :return str: Status of the operation. Possible statuses: 'Accepted' or 'Failed'.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwareUpdate.html
        """
        parameters = {"shouldActivate": should_activate,
                      "shouldResetRadios": should_reset_radios,
                      "inputFileName": sw_package}

        if sw_package.lower().startswith('http'):
            response = self._api_client.execute_procedure("softwareUpdate", parameters, timeout,
                                                          input_file_url=sw_package)
        else:
            response = self._api_client.execute_procedure("softwareUpdate", parameters, timeout,
                                                          input_file_name=sw_package)

        if response is None:
            raise DataNotAvailable("Operation is invalid from Node-B side")

        return response

    def download_and_update_software(self, url, target_bd, should_activate=True, timeout=600, detailed_output=False):
        """
        Download package and perform software update.

        :param string url: File server URL.
        :param string target_bd: Remote path to software package.
        :param boolean should_activate: Activate software flag, defaults set to True.
        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :raises AdminApiProcedureFailureException: If operation on OAM side fails
        the error shall be included in exception, eg. `Status reached: MIGRATION_FAILED`

        :return str: Status of the operation.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwareUpdate.html
        """
        parameters = {"fileServerUrl": url, "targetBd": target_bd, "shouldActivate": should_activate}

        response = self._api_client.execute_customer_procedure("softwareUpdate", parameters, timeout)

        if response is None:
            raise DataNotAvailable("Operation is invalid from Node-B side")

        return response if detailed_output else response.get(self._provided_content.request_message)

    def abort_software_update(self, timeout=60, detailed_output=False):
        """
        Abort software update.

        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :raises DataNotAvailable: Raised if operation is invalid from Node-B side.
        :raises AdminApiProcedureFailureException: If operation on OAM side fails

        :return str: Status of the operation.

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-swDownloadAbort.html
        """

        response = self._api_client.execute_customer_procedure("swDownloadAbort", {}, timeout)

        if response is None:
            raise DataNotAvailable("Operation is invalid from Node-B side")

        return response if detailed_output else response.get(self._provided_content.request_message)

    def rollback_software(self, timeout=300, detailed_output=False):
        """
        Perform a software rollback.

        :param int timeout: Time to wait for positive procedure result.
        :param bool detailed_output: return full request response when True, defaults set to False.
        :return Union[str, dict]: software rollback status
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-swRollback.html
        """

        response = self._api_client.execute_customer_procedure("swRollback", {}, timeout)
        return response if detailed_output else response.get(self._provided_content.request_message)

    def get_sw_update_report(self, target_file_name, timeout=120):
        """
        Get SWDLreport.txt file from BTS

        :param target_file_name: File name for SWDLreport.txt content to be saved.
        :param timeout: Time to wait for positive procedure result.
        :return: str: Empty string.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-swUpdateReport.html
        """

        return self._api_client.execute_procedure("swUpdateReport", {}, timeout, output_file_name=target_file_name)

    def get_software_info(self, timeout=10):
        """
        Get software info.

        :param int timeout: Time to wait for positive procedure result.

        :return: dict: Dictionary containig information about active software.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-swInfo.html
        """

        return self._api_client.execute_infomodel_request("swInfo", {}, timeout)

    def save_sw_history_report(self, target_file_name, timeout=120):
        """
        Saves SW history report

        :param target_file_name: File name for SW history report content to be saved.
        :param timeout: Time to wait for positive procedure result.
        :return: str: Empty string.

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-swHistoryReport.html
        """

        return self._api_client.execute_procedure("swHistoryReport", {}, timeout, output_file_name=target_file_name)

    def software_precheck_local(self, sw_package, precheck_type, timeout=120):
        """
        Software precheck for local file

        :param string sw_package: Path to software package.
        :param string precheck_type: precheck type.
        :param timeout: Time to wait for positive procedure result.
        :return: dict: Dict with precheck result.
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwarePrecheck.html
        """

        return self._api_client.execute_procedure("softwarePrecheck", {"precheckType": precheck_type}, timeout,
                                                  input_file_name=sw_package)

    def software_precheck_remote(self, file_server_url, target_bd, precheck_type, timeout=120):
        """
        Software precheck for remote server

        :param string file_server_url: server url.
        :param string target_bd: targetBd file name.
        :param string precheck_type: precheck type.
        :param timeout: Time to wait for positive procedure result.
        :return: dict: Dict with precheck result.
        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwarePrecheck.html
        """

        return self._api_client.execute_procedure("softwarePrecheck",
                                                  {"fileServerUrl": file_server_url,
                                                   "targetBd": target_bd, "precheckType": precheck_type},
                                                  timeout)

    def software_postcheck(self, timeout=120):
        """
        Software postcheck

        :param timeout: Time to wait for positive procedure result.
        :return: dict: Dict with postcheck result

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-softwarePostcheck.html
        """

        return self._api_client.execute_procedure("softwarePostcheck", {}, timeout)

    def wait_sw_update_possible(self, bts_ready=True, readiness_timeout=600, timeout=700):
        """
        Wait for software update is possible

        :param boolean bts_ready: Bts ready flag. By default set to True.
        :param int readiness_timeout: Timeout for the bts to be ready in seconds (parameter for waitSwUpdatePossible CLI procedure).
        :param int timeout: Timeout for the operation. Should be higher than readiness_timeout.
        :return string: Result of the operation ["ongoing"|"completed"|"failed"|"wait btsReadyForSwUpdate:true succeed"|
        "Procedure didn't finish before timeout : cancellation error"].
        """
        if readiness_timeout > timeout:
            logging.warning("Readiness timeout is higher than KW's timeout!\n"
                            " Adjusting KW's timeout value to meet requirements.")
            timeout = readiness_timeout + 100
        readiness_timeout = readiness_timeout * 1000
        parameters = {"btsReadyForSwUpdate": bts_ready, "timeout": readiness_timeout}
        return self._api_client.execute_infomodel_request("waitForSwUpdatePossible", parameters, timeout)

    def passive_synchronize(self, copy_to_passive=0, comment=None, timeout=60):
        """
        Passive synchronize.

        :param int copy_to_passive: Copy to passive. [0 | 1]. Mandatory parameter.
        :param str comment: Copy to passive comment. Optional
        :param int timeout: Time to wait for positive procedure result.
        :return str: Result of the operation ["ongoing"|"completed"|"failed"].

        More details:
        https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-passiveSynchronize.html
        """
        if copy_to_passive not in (0, 1):
            raise_value_error(param="copy_to_passive",
                              value=str(copy_to_passive),
                              subpage="tutorial-passiveSynchronize.html")

        parameters = {"copyToPassive": copy_to_passive}
        if comment:
            parameters["copyToPassiveComment"] = comment

        return self._api_client.execute_procedure("passiveSynchronize", parameters, timeout)

    def do_sw_activate(self, target_bd, sw_upgrade_type=None, timeout=300):
        """
        Activate installed software.

        :param string target_bd: targetBd file name.
                                 (This is targetBD name which is corresponding with the targetBD in SW update package.)
        :param string sw_upgrade_type: (Optional) Independent SW upgrade type. ['All', 'RuSwOnly']
        :param int timeout: Time to wait for positive procedure result.
        :return str: Result of the operation. ["ongoing"|"completed"|"failed"]

        More details: https://boamui-onion.dynamic.nsn-net.net/branches/master/cli-docs/tutorial-doSwActivate.html
        """
        parameters = {'targetBd': target_bd}
        if sw_upgrade_type is not None:
            if sw_upgrade_type not in ('All', 'RuSwOnly'):
                raise_value_error(param="sw_upgrade_type",
                                  value=str(sw_upgrade_type),
                                  subpage="tutorial-doSwActivate.html")
            parameters['independentSwUpgradeType'] = sw_upgrade_type
        return self._api_client.execute_procedure("doSwActivate", parameters, timeout)
